package main

import (
	"bytes"
	"strings"
	"testing"
)

func env(kv map[string]string) func(string) string {
	return func(key string) string { return kv[key] }
}

func TestRun_Success(t *testing.T) {
	t.Parallel()

	var stderr bytes.Buffer
	code := run(env(map[string]string{
		"GITEA_ACTIONS": "true",
		"GITEA_TOKEN":   "token",
	}), &stderr)

	if code != 0 || stderr.String() != "plugin_schema_version=1\n" {
		t.Fatalf("unexpected result: code=%d stderr=%q", code, stderr.String())
	}
}

func TestRun_Failure(t *testing.T) {
	t.Parallel()

	var stderr bytes.Buffer
	code := run(env(map[string]string{}), &stderr)
	if code != 1 || stderr.Len() == 0 {
		t.Fatalf("unexpected result: code=%d stderr=%q", code, stderr.String())
	}
}

func TestRun_DryRunPrintsDecisionAndReason(t *testing.T) {
	t.Parallel()

	var stdout, stderr bytes.Buffer
	code := runWithStdout(env(map[string]string{
		"SEMREL_DRY_RUN": "true",
	}), &stdout, &stderr)
	if code != 0 {
		t.Fatalf("expected exit code 0 in dry-run, got %d", code)
	}
	if !strings.Contains(stdout.String(), "decision: block") || !strings.Contains(stdout.String(), "reason:") {
		t.Fatalf("unexpected stdout: %q", stdout.String())
	}
	if !strings.Contains(stderr.String(), "[dry-run] condition-gitea-actions: decision=block") {
		t.Fatalf("unexpected stderr: %q", stderr.String())
	}
}
